-- Seed data for assessment questions (Phase 1 Control Flow Assessment)
INSERT INTO questions (assessment_id, question_text, question_type, options, correct_answer, explanation, difficulty, points, order_index, tags) VALUES
-- Assessment 1: Control Flow Assessment
(1, 'What will be the output of: print(2 ** 3 ** 2)?', 'multiple_choice_single', '["64", "512", "256", "Error"]', '512', 'Exponentiation is right-associative: 2 ** (3 ** 2) = 2 ** 9 = 512', 'easy', 1, 1, '["operators", "precedence"]'),
(1, 'Which loop is guaranteed to execute at least once?', 'multiple_choice_single', '["for loop", "while loop", "do-while loop", "None - Python does not have do-while"]', 'None - Python does not have do-while', 'Python does not have a do-while loop construct. while loops check condition first.', 'easy', 1, 2, '["loops"]'),
(1, 'What does the "else" clause on a loop do?', 'multiple_choice_single', '["Runs if loop completes without break", "Runs if loop is never entered", "Runs after every iteration", "Syntax error"]', 'Runs if loop completes without break', 'The else block on a for/while loop executes only if the loop was not terminated by a break statement.', 'medium', 1, 3, '["loops", "else-clause"]'),
(1, 'Complete the code to print numbers 1 to 5:', 'code_completion', '["for i in range(______):\n    print(i)"], '["1, 6"]', 'range(1, 6) produces 1, 2, 3, 4, 5. Range is exclusive of the stop value.', 'easy', 1, 4, '["loops", "range"]'),
(1, 'What is the output of this code?\n```python\nfor i in range(3):\n    if i == 1:\n        continue\n    print(i)\n```', 'code_prediction', '["0 1 2", "0 2", "1 2", "0 1"]', '0 2', 'continue skips the rest of the current iteration. When i=1, print is skipped.', 'easy', 1, 5, '["loops", "continue"]'),
(1, 'Fix the infinite loop:\n```python\ni = 0\nwhile i < 5:\n    print(i)\n```', 'debugging', '["i = 0\nwhile i < 5:\n    print(i)\n    i += 1"]', 'i = 0\nwhile i < 5:\n    print(i)\n    i += 1', 'The loop variable i is never incremented, causing infinite loop. Add i += 1 inside the loop.', 'easy', 1, 6, '["loops", "debugging", "infinite-loop"]'),
(1, 'What does "break" do in a nested loop?', 'multiple_choice_single', '["Exits all loops", "Exits only the innermost loop", "Exits the outer loop", "Continues to next iteration of outer loop"]', 'Exits only the innermost loop', 'break only exits the loop it is directly inside. To exit outer loops, use a flag or function return.', 'medium', 1, 7, '["loops", "break", "nested"]'),
(1, 'Which is the correct way to check if a list is empty?', 'multiple_choice_single', '["if len(my_list) == 0:", "if my_list == []:", "if not my_list:", "All of the above work"]', 'if not my_list:', 'All three work, but "if not my_list:" is the most Pythonic and efficient.', 'easy', 1, 8, '["conditionals", "pythonic"]'),
(1, 'What is the output?\n```python\nx = 10\nif x > 5:\n    if x > 15:\n        print("A")\n    else:\n        print("B")\nelse:\n    print("C")\n```', 'code_prediction', '["A", "B", "C", "Error"]', 'B', 'x=10: x>5 is True, so enter first if. x>15 is False, so execute else: print("B")', 'easy', 1, 9, '["conditionals", "nested"]'),
(1, 'Complete: Check if a number is even', 'code_completion', '["def is_even(n):\n    return n ______ 2 == 0"]', '["%"]', 'The modulo operator % returns the remainder. Even numbers have remainder 0 when divided by 2.', 'easy', 1, 10, '["operators", "modulo"]'),
(1, 'What will this print?\n```python\nfor i in range(2, 10, 2):\n    print(i, end=" ")\n```', 'code_prediction', '["2 4 6 8", "2 4 6 8 10", "0 2 4 6 8", "Error"]', '2 4 6 8', 'range(2, 10, 2) starts at 2, stops before 10, steps by 2.', 'easy', 1, 11, '["loops", "range"]'),
(1, 'Debug: This should print "Found!" when 5 is in the list\n```python\nnumbers = [1, 2, 3, 4, 5]\nfor n in numbers:\n    if n = 5:\n        print("Found!")\n```', 'debugging', '["numbers = [1, 2, 3, 4, 5]\nfor n in numbers:\n    if n == 5:\n        print(\"Found!\")"]', 'numbers = [1, 2, 3, 4, 5]\nfor n in numbers:\n    if n == 5:\n        print("Found!")', 'Assignment (=) used instead of comparison (==) in the if condition.', 'easy', 1, 12, '["debugging", "comparison"]'),
(1, 'What does "pass" do in a loop?', 'multiple_choice_single', '["Skips to next iteration", "Exits the loop", "Does nothing (placeholder)", "Prints a newline"]', 'Does nothing (placeholder)', 'pass is a null statement used as a placeholder when syntax requires a statement but no action is needed.', 'easy', 1, 13, '["loops", "pass"]'),
(1, 'Which is an off-by-one error?', 'multiple_choice_single', '["for i in range(10):", "for i in range(1, 11):", "for i in range(0, 10):", "Both A and C for 1-10"]', 'Both A and C for 1-10', 'range(10) gives 0-9 (10 numbers). For 1-10, use range(1, 11) or range(10) with i+1.', 'medium', 1, 14, '["loops", "off-by-one", "range"]'),
(1, 'Predict output:\n```python\ncount = 0\nwhile count < 3:\n    print(count)\n    count += 1\nelse:\n    print("Done")\n```', 'code_prediction', '["0 1 2 Done", "0 1 2", "Done 0 1 2", "Error"]', '0 1 2 Done', 'The else clause executes after the loop completes normally (without break).', 'medium', 1, 15, '["loops", "else-clause"]'),

-- Assessment 2: Phase 1 Diagnostic
(2, 'What is the result of 10 // 3?', 'multiple_choice_single', '["3.333", "3", "4", "3.0"]', '3', 'Floor division (//) returns the largest integer less than or equal to the result.', 'easy', 1, 1, '["operators"]'),
(2, 'Which data type is immutable?', 'multiple_choice_single', '["list", "dict", "set", "tuple"]', 'tuple', 'Tuples are immutable; lists, dicts, and sets are mutable.', 'easy', 1, 2, '["data-types", "mutability"]'),
(2, 'What does list.append() return?', 'multiple_choice_single', '["The new list", "The appended item", "None", "The length of the list"]', 'None', 'list.append() modifies the list in place and returns None.', 'easy', 1, 3, '["lists", "methods"]'),
(2, 'How do you handle multiple exceptions?', 'multiple_choice_single', '["try:\n    ...\nexcept ValueError, TypeError:\n    ...", "try:\n    ...\nexcept (ValueError, TypeError):\n    ...", "try:\n    ...\nexcept ValueError or TypeError:\n    ...", "try:\n    ...\nexcept ValueError:\n    ...\nexcept TypeError:\n    ..."]', 'try:\n    ...\nexcept (ValueError, TypeError):\n    ...', 'Use a tuple of exception types in a single except clause.', 'medium', 1, 4, '["exceptions"]'),
(2, 'What is a closure?', 'multiple_choice_single', '["A function that calls itself", "A function that captures variables from its enclosing scope", "A function with no parameters", "A function that returns another function"]', 'A function that captures variables from its enclosing scope', 'A closure is a function that remembers values from its enclosing lexical scope even when called outside that scope.', 'medium', 1, 5, '["functions", "closures"]'),
(2, 'What is the time complexity of list.append()?', 'multiple_choice_single', '["O(1)", "O(n)", "O(log n)", "O(n²)"]', 'O(1)', 'list.append() is amortized O(1) - constant time on average.', 'easy', 1, 6, '["complexity", "lists"]'),
(2, 'What does *args do in a function definition?', 'multiple_choice_single', '["Accepts keyword arguments", "Accepts variable positional arguments", "Accepts variable keyword arguments", "Makes all arguments required"]', 'Accepts variable positional arguments', '*args collects extra positional arguments into a tuple. **kwargs collects keyword arguments.', 'easy', 1, 7, '["functions", "args"]'),
(2, 'Which method removes and returns the last item of a list?', 'multiple_choice_single', '["list.pop()", "list.remove()", "list.del()", "list.drop()"]', 'list.pop()', 'pop() removes and returns the last item (or item at index). remove() removes by value but returns None.', 'easy', 1, 8, '["lists", "methods"]'),
(2, 'What is the output?\n```python\ndef func(x, y=10):\n    return x + y\nprint(func(5))\n```', 'code_prediction', '["15", "Error", "5", "None"]', '15', 'Default parameter y=10 is used when only one argument is provided. 5 + 10 = 15.', 'easy', 1, 9, '["functions", "default-params"]'),
(2, 'What does the "with" statement do for file handling?', 'multiple_choice_single', '["Opens file in write mode", "Automatically closes the file", "Creates a new file", "Locks the file"]', 'Automatically closes the file', 'with ensures the file is properly closed even if an exception occurs. It is a context manager.', 'easy', 1, 10, '["file-io", "context-manager"]');
